def forward(groups):
    sp1, lifetime = groups
    if '<' in lifetime:
        duration = int(lifetime[1:]) * 60
        is_less_than = 1
    else:
        is_less_than = 0
        minutes, seconds = map(int, lifetime.split(':'))
        duration = minutes * 60 + seconds
    return {'stored': [duration], 'layout': [len(sp1), is_less_than]}

def inverse(record):
    duration = int(record['stored'][0])
    layout = record.get('layout', [])
    sp1_len = int(layout[0])
    is_less_than = int(layout[1])
    if is_less_than:
        lifetime = f"<{duration // 60}"
    else:
        minutes = duration // 60
        seconds = duration % 60
        lifetime = f"{minutes:02}:{seconds:02}"
    return 'lifetime' + (' ' * sp1_len) + lifetime
